NAME = 'VulgSistine: Vulgata Sistina'
BOOK = 'Revelation of John'

CHAPTERS = {
    1: {
        1: 'Apocalypsis Iesu Christi, quam dedit illi Deus palam facere servis suis, quae oportet fieri cito: et significavit, mittens per Angelum suum servo suo Ioanni,',
        2: 'qui testimonium perhibuit verbo Dei, et testimonium Iesu Christi, quaecumque vidit.',
        3: 'Beatus, qui legit, et audit verba prophetiae huius: et servat ea, quae in ea scripta sunt: tempus enim prope est.',
        4: 'Ioannes septem Ecclesiis, quae sunt in Asia. Gratia vobis, et pax ab eo, qui est, et qui erat, et qui venturus est: et a septem spiritibus, qui in conspectu throni eius sunt:',
        5: 'et a Iesu Christo, qui est testis fidelis, primogenitus mortuorum, et princeps regum terrae, qui dilexit nos, et lavit nos a peccatis nostris in sanguine suo,',
        6: 'et fecit nos regnum, et sacerdotes Deo et Patri suo: ipsi gloria, et imperium in saecula saeculorum: Amen.',
        7: 'Ecce venit cum nubibus, et videbit eum omnis oculus, et qui eum pupugerunt. Et plangent se super eum omnes tribus terrae: Etiam: Amen.',
        8: 'Ego sum alpha, et omega, principium, et finis, dicit Dominus Deus: qui est, et qui erat, et qui venturus est, omnipotens.',
        9: 'Ego Ioannes frater vester, et particeps in tribulatione, et regno et patientia in Christo Iesu: fui in insula, quae appellatur Patmos propter verbum Dei, et testimonium Iesu:',
        10: 'Fui in spiritu in Dominica die, et audivi post me vocem magnam tamquam tubae,',
        11: 'dicentis: Quod vides, scribe in libro: et mitte septem Ecclesiis, quae sunt in Asia, Epheso, et Smyrnae, et Pergamo, et Thyatirae, et Sardis, et Philadelphiae, et Laodiciae:',
        12: 'Et conversus sum ut viderem vocem, quae loquebatur mecum: Et conversus vidi septem candelabra aurea:',
        13: 'et in medio septem candelabrorum aureorum similem filio hominis, vestitum podere, et praecinctum ad mamillas zona aurea:',
        14: 'caput autem eius, et capilli erant candidi tamquam lana alba, et tamquam nix, et oculi eius tamquam flamma ignis,',
        15: 'et pedes eius similes aurichalco, sicut in camino ardenti, et vox illius tamquam vox aquarum multarum:',
        16: 'et habebat in dextera sua stellas septem: et de ore eius gladius utraque parte acutus exibat: et facies eius sicut sol lucet in virtute sua.',
        17: 'Et cum vidissem eum, cecidi ad pedes eius tamquam mortuus. Et posuit dexteram suam super me, dicens: Noli timere: ego sum primus, et novissimus,',
        18: 'et vivus, et fui mortuus, et ecce sum vivens in saecula saeculorum, et habeo claves mortis, et inferni.',
        19: 'Scribe ergo quae vidisti, et quae sunt, et quae oportet fieri post haec.',
        20: 'Sacramentum septem stellarum, quas vidisti in dextera mea, et septem candelabra aurea: septem stellae Angeli sunt septem Ecclesiarum: et candelabra septem, septem Ecclesiae sunt.',
    },
    2: {
        1: 'Et Angelo Ephesi Ecclesiae scribe: Haec dicit, qui tenet septem stellas in dextera sua, qui ambulat in medio septem candelabrorum aureorum:',
        2: 'Scio opera tua, et laborem, et patientiam tuam, et quia non potes sustinere malos: et tentasti eos, qui se dicunt Apostolos esse, et non sunt: et invenisti eos mendaces:',
        3: 'et patientiam habes, et sustinuisti propter nomen meum, et non defecisti.',
        4: 'Sed habeo adversum te pauca, quod charitatem tuam primam reliquisti.',
        5: 'Memor esto itaque unde excideris: et age poenitentiam, et prima opera fac. sin autem, veniam tibi cito, et movebo candelabrum tuum de loco suo, nisi poenitentiam egeris.',
        6: 'Sed hoc habes, quia odisti facta Nicolaitarum, quae et ego odi.',
        7: 'Qui habet aurem, audiat quid Spiritus dicat Ecclesiis: Vincenti dabo edere de ligno vitae, quod est in Paradiso Dei mei.',
        8: 'Et Angelo Smyrnae Ecclesiae scribe: Haec dicit primus, et novissimus, qui fuit mortuus, et vivit:',
        9: 'Scio tribulationem tuam, et paupertatem tuam, sed dives es: et blasphemaris ab his, qui se dicunt Iudaeos esse, et non sunt, sed sunt synagogae satanae.',
        10: 'Nihil horum timeas quae passurus es. Ecce missurus est diabolus aliquos ex vobis in carcerem ut tentemini: et habebitis tribulationem diebus decem. Esto fidelis usque ad mortem, et dabo tibi coronam vitae.',
        11: 'Qui habet aurem, audiat quid Spiritus dicat Ecclesiis: Qui vicerit, non laedetur a morte secunda.',
        12: 'Et Angelo Pergami Ecclesiae scribe: Haec dicit qui habet rhomphaeam ex utraque parte acutam:',
        13: 'Scio ubi habitas, ubi sedes est satanae: et tenes nomen meum, et non negasti fidem meam. Et in diebus illis Antipas testis meus fidelis, qui occisus est apud vos, ubi satanas habitat.',
        14: 'Sed habeo adversus te pauca: quia habes illic tenentes doctrinam Balaam, qui docebat Balac mittere scandalum coram filiis Israel, edere, et fornicari:',
        15: 'ita habes et tu tenentes doctrinam Nicolaitarum.',
        16: 'Similiter poenitentiam age: si quo minus veniam tibi cito, et pugnabo cum illis in gladio oris mei.',
        17: 'Qui habet aurem, audiat quid Spiritus dicat Ecclesiis: Vincenti dabo manna absconditum, et dabo illi calculum candidum: et in calculo nomen novum scriptum, quod nemo scit, nisi qui accipit.',
        18: 'Et Angelo Thyatirae Ecclesiae scribe: Haec dicit Filius Dei, qui habet oculos tamquam flammam ignis, et pedes eius similes aurichalco:',
        19: 'Novi opera tua, et fidem, et charitatem tuam, et ministerium, et patientiam tuam, et opera tua novissima plura prioribus.',
        20: 'Sed habeo adversus te pauca: quia permittis mulierem Iezabel, quae se dicit propheten, docere, et seducere servos meos, fornicari, et manducare de idolothytis.',
        21: 'Et dedi illi tempus ut poenitentiam ageret: et non vult poenitere a fornicatione sua.',
        22: 'Ecce ego mitto eam in lectum: et qui moechantur cum ea, in tribulatione maxima erunt, nisi poenitentiam ab operibus suis egerint.',
        23: 'et filios eius interficiam in morte, et scient omnes Ecclesiae, quia ego sum scrutans renes, et corda: et dabo unicuique vestrum secundum opera sua. Vobis autem dico,',
        24: 'et ceteris quia Thyatirae estis: Quicumque non habent doctrinam hanc, et qui non cognoverunt altitudines satanae, quemadmodum dicunt, non mittam super vos aliud pondus:',
        25: 'tamen id, quod habetis, tenete donec veniam.',
        26: 'Et qui vicerit, et custodierit usque in finem opera mea, dabo illi potestatem super Gentes,',
        27: 'et reget eas in virga ferrea, et tamquam vas figuli confringentur,',
        28: 'sicut et ego accepi a Patre meo: et dabo illi stellam matutinam.',
        29: 'Qui habet aurem, audiat quid Spiritus dicat Ecclesiis.',
    },
    3: {
        1: 'Et Angelo Ecclesiae Sardis scribe: Haec dicit qui habet septem Spiritus Dei, et septem stellas: Scio opera tua, quia nomen habes quod vivas, et mortuus es.',
        2: 'Esto vigilans, et confirma cetera, quae moritura erant. Non enim invenio opera tua plena coram Deo meo.',
        3: 'In mente ergo habe qualiter acceperis, et audieris, et serva, et poenitentiam age. Si ergo non vigilaveris, veniam ad te tamquam fur, et nescies qua hora veniam ad te.',
        4: 'Sed habes pauca nomina in Sardis, qui non inquinaverunt vestimenta sua: et ambulabunt mecum in albis, quia digni sunt.',
        5: 'Qui vicerit, sic vestietur vestimentis albis, et non delebo nomen eius de Libro vitae, et confitebor nomen eius coram Patre meo, et coram angelis eius.',
        6: 'Qui habet aurem, audiat quid Spiritus dicat Ecclesiis.',
        7: 'Et Angelo Philadelphiae ecclesiae scribe: Haec dicit Sanctus et Verus, qui habet clavem David: qui aperit, et nemo claudit: claudit, et nemo aperit:',
        8: 'Scio opera tua. Ecce dedi coram te ostium apertum, quod nemo potest claudere: quia modicam habes virtutem, et servasti verbum meum, et non negasti nomen meum.',
        9: 'Ecce dabo de synagoga satanae, qui dicunt se Iudaeos esse, et non sunt, sed mentiuntur: Ecce faciam illos ut veniant, et adorent ante pedes tuos: et scient quia ego dilexi te',
        10: 'quoniam servasti verbum patientiae meae, et ego servabo te ab hora tentationis, quae ventura est in orbem universum tentare habitantes in terra.',
        11: 'Ecce venio cito: tene quod habes, ut nemo accipiat coronam tuam.',
        12: 'Qui vicerit, faciam illum columnam in templo Dei mei, et foras non egredietur amplius: et scribam super eum nomen Dei mei, et nomen civitatis Dei mei novae Ierusalem, quae descendit de caelo a Deo meo, et nomen meum novum.',
        13: 'Qui habet aurem, audiat quid Spiritus dicat Ecclesiis.',
        14: 'Et Angelo Laodiciae ecclesiae scribe: Haec dicit: Amen, testis fidelis, et verus, qui est principium creaturae Dei.',
        15: 'Scio opera tua: quia neque frigidus es, neque calidus: utinam frigidus esses, aut calidus:',
        16: 'sed quia tepidus es, et nec frigidus, nec calidus, incipiam te evomere ex ore meo.',
        17: 'quia dicis: dives sum, et locupletatus, et nullius egeo: et nescis quia tu es miser, et miserabilis, et pauper, et caecus, et nudus.',
        18: 'Suadeo tibi emere a me aurum ignitum probatum ut locuples fias, et vestimentis albis induaris, ut non appareat confusio nuditatis tuae, et collyrio inunge oculos tuos ut videas.',
        19: 'Ego quos amo, arguo, et castigo. Aemulare ergo, et poenitentiam age.',
        20: 'Ecce sto ad ostium, et pulso: siquis audierit vocem meam, et aperuerit mihi ianuam, intrabo ad illum, et coenabo cum illo, et ipse mecum.',
        21: 'Qui vicerit, dabo ei sedere mecum in throno meo: sicut et ego vici, et sedi cum patre meo in throno eius.',
        22: 'Qui habet aurem, audiat quid Spiritus dicat Ecclesiis.',
    },
    4: {
        1: 'Post haec vidi: et ecce ostium apertum in caelo, et vox prima, quam audivi tamquam tubae loquentis mecum, dicens: Ascende huc, et ostendam tibi quae oportet fieri cito post haec.',
        2: 'Statim fui in spiritu: et ecce sedes posita erat in caelo, et supra sedem sedens.',
        3: 'Et qui sedebat similis erat aspectui lapidis iaspidis, et sardinis: et iris erat in circuitu sedis similis visioni smaragdinae.',
        4: 'Et in circuitu sedis sedilia vigintiquattuor: et super thronos vigintiquattuor seniores sedentes, circumamicti vestimentis albis, et in capitibus eorum coronae aureae:',
        5: 'Et de throno procedebant fulgura, et voces, et tonitrua: et septem lampades ardentes ante thronum, qui sunt septem spiritus Dei.',
        6: 'Et in conspectu sedis tamquam mare vitreum simile crystallo: et in medio sedis, et in circuitu sedis quattuor animalia plena oculis ante et retro.',
        7: 'Et animal primum simile leoni, et secundum animal simile vitulo, et tertium animal habens faciem quasi hominis, et quartum animal simile aquilae volanti.',
        8: 'Et quattuor animalia, singula eorum habebant alas senas in circuitu: et intus plena sunt oculis: et requiem non habebant die ac nocte, dicentia: Sanctus, Sanctus, Sanctus Dominus Deus omnipotens, qui erat, et qui est, et qui venturus est.',
        9: 'Et cum darent illa animalia gloriam, et honorem, et benedictionem sedenti super thronum, viventi in saecula saeculorum,',
        10: 'procidebant vigintiquattuor seniores ante sedentem in throno, et adorabant viventem in saecula saeculorum, et mittebant coronas suas ante thronum dicentes:',
        11: 'Dignus es Domine Deus noster accipere gloriam, et honorem, et virtutem: quia tu creasti omnia, et propter voluntatem tuam erant, et creata sunt.',
    },
    5: {
        1: 'Et vidi in dextera sedentis supra thronum, librum scriptum intus et foris, signatum sigillis septem.',
        2: 'Et vidi Angelum fortem, praedicantem voce magna: Quis est dignus aperire librum, et solvere signacula eius?',
        3: 'Et nemo poterat neque in caelo, neque in terra, neque subtus terram aperire librum, neque respicere illum.',
        4: 'Et ego flebam multum, quoniam nemo dignus inventus est aperire librum, nec videre eum.',
        5: 'Et unus de senioribus dixit mihi: Ne fleveris: ecce vicit leo de tribu Iuda, radix David, aperire librum, et solvere septem signacula eius.',
        6: 'Et vidi: et ecce in medio throni et quattuor animalium, et in medio seniorum, agnum stantem tamquam occisum, habentem cornua septem, et oculos septem: qui sunt septem spiritus Dei, missi in omnem terram.',
        7: 'Et venit: et accepit de dextera sedentis in throno librum.',
        8: 'Et cum aperuisset librum, quattuor animalia, et vigintiquattuor seniores ceciderunt coram agno, habentes singuli citharas, et phialas aureas plenas odoramentorum, quae sunt orationes sanctorum:',
        9: 'et cantabant canticum novum, dicentes: Dignus es Domine accipere librum, et aperire signacula eius: quoniam occisus es, et redemisti nos Deo in sanguine tuo ex omni tribu, et lingua, et populo, et natione:',
        10: 'et fecisti nos Deo nostro regnum, et sacerdotes: et regnabimus super terram.',
        11: 'Et vidi, et audivi vocem angelorum multorum in circuitu throni, et animalium, et seniorum: et erat numerus eorum millia millium,',
        12: 'dicentium voce magna: Dignus est Agnus, qui occisus est, accipere virtutem, et divinitatem, et sapientiam, et fortitudinem, et honorem, et gloriam, et benedictionem.',
        13: 'Et omnem creaturam, quae in caelo est, et super terram, et sub terra, et quae sunt in mari, et quae in eo: omnes audivi dicentes: Sedenti in throno, et Agno: benedictio, et honor, et gloria, et potestas in saecula saeculorum.',
        14: 'Et quattuor animalia dicebant: Amen. Et viginti quattuor seniores ceciderunt in facies suas: et adoraverunt viventem in saecula saeculorum.',
    },
    6: {
        1: 'Et vidi quod aperuisset Agnus unum de septem sigillis, et audivi unum de quattuor animalibus, dicens, tamquam vocem tonitrui: Veni, et vide.',
        2: 'Et vidi: et ecce equus albus, et qui sedebat super illum habebat arcum, et data est ei corona, et exivit vincens ut vinceret.',
        3: 'Et cum aperuisset sigillum secundum, audivi secundum animal, dicens: Veni, et vide.',
        4: 'Et exivit alius equus rufus: et qui sedebat super illum, datum est ei ut sumeret pacem de terra, et ut invicem se interficiant, et datus est ei gladius magnus.',
        5: 'Et cum aperuisset sigillum tertium, audivi tertium animal, dicens: Veni, et vide. Et ecce equus niger: et qui sedebat super illum, habebat stateram in manu sua.',
        6: 'Et audivi tamquam vocem in medio quattuor animalium dicentium: Bilibris tritici denario uno, et tres bilibres hordei denario uno, et vinum, et oleum ne laeseris.',
        7: 'Et cum aperuisset sigillum quartum, audivi vocem quarti animalis dicentis: Veni, et vide.',
        8: 'Et ecce equus pallidus: et qui sedebat super eum, nomen illi Mors, et infernus sequebatur eum, et data est illi potestas super quattuor partes terrae, interficere gladio, fame, et morte, et bestiis terrae.',
        9: 'Et cum aperuisset sigillum quintum: vidi subtus altare animas interfectorum propter verbum Dei, et propter testimonium, quod habebant,',
        10: 'et clamabant voce magna, dicentes: Usquequo Domine, (sanctus, et verus) non iudicas, et non vindicas sanguinem nostrum de iis, qui habitant in terra?',
        11: 'Et datae sunt illis singulae stolae albae: et dictum est illis ut requiescerent adhuc tempus modicum donec compleantur conservi eorum, et fratres eorum, qui interficiendi sunt sicut et illi.',
        12: 'Et vidi cum aperuisset sigillum sextum: et ecce terraemotus magnus factus est, et sol factus est niger tamquam saccus cilicinus: et luna tota facta est sicut sanguis:',
        13: 'et stellae de caelo ceciderunt super terram, sicut ficus emittit grossos suos cum a vento magno movetur.',
        14: 'et caelum recessit sicut liber involutus: et omnis mons, et insulae de locis suis motae sunt:',
        15: 'et reges terrae, et principes, et tribuni, et divites, et fortes, et omnis servus, et liber absconderunt se in speluncis, et in petris montium:',
        16: 'et dicunt montibus, et petris: Cadite super nos, et abscondite nos a facie sedentis super thronum, et ab ira Agni:',
        17: 'quoniam venit dies magnus irae ipsorum: et quis poterit stare?',
    },
    7: {
        1: 'Post haec vidi quattuor Angelos stantes super quattuor angulos terrae, tenentes quattuor ventos terrae ne flarent super terram, neque super mare, neque in ullam arborem.',
        2: 'Et vidi alterum Angelum ascendentem ab ortu solis, habentem signum Dei vivi: et clamavit voce magna quattuor Angelis, quibus datum est nocere terrae, et mari,',
        3: 'dicens: Nolite nocere terrae, et mari, neque arboribus, quoadusque signemus servos Dei nostri in frontibus eorum.',
        4: 'Et audivi numerum signatorum, centum quadraginta quattuor millia signati, ex omni tribu filiorum Israel.',
        5: 'Ex tribu Iuda duodecim millia signati: Ex tribu Ruben duodecim millia signati: Ex tribu Gad duodecim millia signati:',
        6: 'Ex tribu Aser duodecim millia signati: Ex tribu Nephthali duodecim millia signati: Ex tribu Manasse duodecim millia signati:',
        7: 'Ex tribu Simeon duodecim millia signati: Ex tribu Levi duodecim millia signati: Ex tribu Issachar duodecim millia signati:',
        8: 'Ex tribu Zabulon duodecim millia signati: Ex tribu Ioseph duodecim millia signati: Ex tribu Beniamin duodecim millia signati.',
        9: 'Post haec vidi turbam magnam, quam dinumerare nemo poterat ex omnibus gentibus, et tribubus, et populis, et linguis: stantes ante thronum, et in conspectu Agni, amicti stolis albis, et palmae in manibus eorum:',
        10: 'et clamabant voce magna dicentes: Salus Deo nostro, qui sedet super thronum, et Agno.',
        11: 'Et omnes Angeli stabant in circuitu throni, et seniorum, et quattuor animalium: et ceciderunt in conspectu throni in facies suas, et adoraverunt Deum,',
        12: 'dicentes, Amen. Benedictio, et claritas, et sapientia, et gratiarum actio, honor, et virtus, et fortitudo Deo nostro in saecula saeculorum, Amen.',
        13: 'Et respondit unus de senioribus, et dixit mihi: Hi, qui amicti sunt stolis albis, qui sunt? et unde venerunt?',
        14: 'Et dixi illi: Domine mi, tu scis. Et dixit mihi: Hi sunt, qui venerunt de tribulatione magna, et laverunt stolas suas, et dealbaverunt eas in sanguine Agni.',
        15: 'ideo sunt ante thronum Dei, et serviunt ei die ac nocte in templo eius: et qui sedet in throno, habitabit super illos:',
        16: 'non esurient, neque sitient amplius, nec cadet super illos sol, neque ullus aestus:',
        17: 'quoniam Agnus, qui in medio throni est, reget illos, et deducet eos ad vitae fontes aquarum, et absterget Deus omnem lacrymam ab oculis eorum.',
    },
    8: {
        1: 'Et cum aperuisset sigillum septimum, factum est silentium in caelo, quasi media hora.',
        2: 'Et vidi septem Angelos stantes in conspectu Dei: et datae sunt illis septem tubae.',
        3: 'Et alius Angelus venit, et stetit ante altare habens turibulum aureum: et data sunt illi incensa multa, ut daret de orationibus sanctorum omnium super altare aureum, quod est ante thronum Dei.',
        4: 'Et ascendit fumus incensorum de orationibus sanctorum de manu Angeli coram Deo.',
        5: 'Et accepit Angelus turibulum aureum, et implevit illud de igne altaris, et misit in terram, et facta sunt tonitrua, et voces, et fulgura, et terraemotus magnus.',
        6: 'Et septem Angeli, qui habebant septem tubas, praeparaverunt se ut tuba canerent.',
        7: 'Et primus Angelus tuba cecinit, et facta est grando, et ignis, mista in sanguine, et missum est in terram, et tertia pars terrae combusta est, et tertia pars arborum concremata est, et omne foenum viride combustum est.',
        8: 'Et secundus Angelus tuba cecinit: et tamquam mons magnus igne ardens missus est in mare, et facta est tertia pars maris sanguis,',
        9: 'et mortua est tertia pars creaturae eorum, quae habebant animas in mari, et tertia pars navium interiit.',
        10: 'Et tertius Angelus tuba cecinit: et cecidit de caelo stella magna, ardens tamquam facula, et cecidit in tertiam partem fluminum, et in fontes aquarum:',
        11: 'et nomen stellae dicitur Absinthium; et facta est tertia pars aquarum in absinthium: et multi hominum mortui sunt de aquis, quia amarae factae sunt.',
        12: 'Et quartus Angelus tuba cecinit: et percussa est tertia pars solis, et tertia pars lunae, et tertia pars stellarum, ita ut obscuraretur tertia pars eorum, et diei non luceret pars tertia, et noctis similiter.',
        13: 'Et vidi, et audivi vocem unius aquilae volantis per medium caeli, dicentis voce magna: Vae, vae, vae habitantibus in terra de ceteris vocibus trium Angelorum, qui erant tuba canituri.',
    },
    9: {
        1: 'Et quintus Angelus tuba cecinit: et vidi stellam de caelo cecidisse in terram, et data est ei clavis putei abyssi.',
        2: 'Et aperuit puteum abyssi: et ascendit fumus putei, sicut fumus fornacis magnae: et obscuratus est sol, et aer de fumo putei:',
        3: 'Et de fumo putei exierunt locustae in terram, et data est illis potestas, sicut habent potestatem scorpiones terrae:',
        4: 'et praeceptum est illis ne laederent foenum terrae, neque omne viride, neque omnem arborem: nisi tantum homines, qui non habent signum Dei in frontibus suis.',
        5: 'Et datum est illis ne occiderent eos: sed ut cruciarent mensibus quinque: et cruciatus eorum, ut cruciatus scorpii cum percutit hominem.',
        6: 'Et in diebus illis quaerent homines mortem, et non invenient eam: et desiderabunt mori, et fugiet mors ab eis.',
        7: 'Et similitudines locustarum, similes equis paratis in proelium: et super capita earum tamquam coronae similes auro: et facies earum tamquam facies hominum.',
        8: 'Et habebant capillos sicut capillos mulierum: et dentes earum, sicut dentes leonum erant:',
        9: 'et habebant loricas sicut loricas ferreas, et vox alarum earum sicut vox curruum equorum multorum currentium in bellum:',
        10: 'et habebant caudas similes scorpionum, et aculei erant in caudis earum: et potestas earum nocere hominibus mensibus quinque:',
        11: 'et habebant super se regem angelum abyssi, cui nomen Hebraice Abaddon, Graece autem Apollyon, Latine habens nomen Exterminans.',
        12: 'Vae unum abiit, et ecce veniunt adhuc duo vae post haec.',
        13: 'Et sextus Angelus tuba cecinit: et audivi vocem unam ex quattuor cornibus altaris aurei, quod est ante oculos Dei,',
        14: 'dicentem sexto Angelo, qui habebat tubam: Solve quattuor angelos, qui alligati sunt in flumine magno Euphrate.',
        15: 'Et soluti sunt quattuor Angeli, qui parati erant in horam, et diem, et mensem, et annum: ut occiderent tertiam partem hominum.',
        16: 'Et numerus equestris exercitus vicies millies dena millia. Et audivi numerum eorum.',
        17: 'Et ita vidi equos in visione: et qui sedebant super eos, habebant loricas igneas, et hyacinthinas, et sulphureas, et capita equorum erant tamquam capita leonum: et de ore eorum procedit ignis, et fumus, et sulphur.',
        18: 'Et ab his tribus plagis occisa est tertia pars hominum de igne, et de fumo, et sulphure, quae procedebant de ore ipsorum.',
        19: 'Potestas enim equorum in ore eorum est, et in caudis eorum. nam caudae eorum similes serpentibus, habentes capita: et in his nocent.',
        20: 'Et ceteri homines, qui non sunt occisi in his plagis, neque poenitentiam egerunt de operibus manuum suarum, ut non adorarent daemonia, et simulachra aurea, et argentea, et aerea, et lapidea, et lignea, quae neque videre possunt, neque audire, neque ambulare,',
        21: 'et non egerunt poenitentiam ab homicidiis suis, neque a veneficiis suis, neque a fornicatione sua, neque a furtis suis.',
    },
    10: {
        1: 'Et vidi alium Angelum fortem descendentem de caelo amictum nube, et iris in capite eius, et facies eius erat ut sol, et pedes eius tamquam columnae ignis:',
        2: 'et habebat in manu sua libellum apertum: et posuit pedem suum dextrum super mare, sinistrum autem super terram:',
        3: 'et clamavit voce magna, quemadmodum cum leo rugit. Et cum clamasset, locuta sunt septem tonitrua voces suas.',
        4: 'Et cum locuta fuissent septem tonitrua voces suas, et ego scripturus eram: et audivi vocem de caelo dicentem mihi: Signa quae locuta sunt septem tonitrua: et noli ea scribere.',
        5: 'Et angelus, quem vidi stantem super mare, et super terram, levavit manum suam ad caelum:',
        6: 'et iuravit per viventem in saecula saeculorum, qui creavit caelum, et ea quae in eo sunt: et terram, et ea quae in ea sunt: et mare, et ea quae in eo sunt: Quia tempus non erit amplius:',
        7: 'sed in diebus vocis septimi angeli, cum coeperit tuba canere, consummabitur mysterium Dei, sicut evangelizavit per servos suos Prophetas.',
        8: 'Et audivi vocem de caelo iterum loquentem mecum, et dicentem: Vade, et accipe librum apertum de manu angeli stantis super mare, et super terram.',
        9: 'Et abii ad angelum, dicens ei, ut daret mihi librum. Et dixit mihi: Accipe librum, et devora illum: et faciet amaricari ventrem tuum, sed in ore tuo erit dulce tamquam mel.',
        10: 'Et accepi librum de manu angeli, et devoravi illum: et erat in ore meo tamquam mel dulce: et cum devorassem eum, amaricatus est venter meus:',
        11: 'et dixit mihi: Oportet te iterum prophetare Gentibus, et populis, et linguis, et regibus multis.',
    },
    11: {
        1: 'Et datus est mihi calamus similis virgae, et dictum est mihi: Surge, et metire templum Dei, et altare, et adorantes in eo.',
        2: 'atrium autem, quod est infra templum, eiice foras, et ne metiaris illud: quoniam datum est Gentibus, et civitatem sanctam calcabunt mensibus quadraginta duobus:',
        3: 'et dabo duobus testibus meis, et prophetabunt diebus mille ducentis sexaginta, amicti saccis.',
        4: 'Hi sunt duae olivae, et duo candelabra in conspectu Domini terrae stantia.',
        5: 'Et si quis voluerit eos nocere, ignis exiet de ore eorum, et devorabit inimicos eorum: et si quis voluerit eos laedere, sic oportet eum occidi.',
        6: 'Hi habent potestatem claudendi caelum, ne pluat diebus prophetiae ipsorum: et potestatem habent super aquas convertendi eas in sanguinem, et percutere terram omni plaga quotiescumque voluerint.',
        7: 'Et cum finierint testimonium suum, bestia, quae ascendit de abysso, faciet adversum eos bellum, et vincet illos, et occidet eos.',
        8: 'Et corpora eorum iacebunt in plateis civitatis magnae, quae vocatur spiritualiter Sodoma, et Aegyptus, ubi et Dominus eorum crucifixus est.',
        9: 'Et videbunt de tribubus, et populis, et linguis, et Gentibus corpora eorum per tres dies, et dimidium: et corpora eorum non sinent poni in monumentis.',
        10: 'et inhabitantes terram gaudebunt super illos, et iucundabuntur: et munera mittent invicem, quoniam hi duo prophetae cruciaverunt eos, qui habitabant super terram.',
        11: 'Et post dies tres, et dimidium, spiritus vitae a Deo intravit in eos. Et steterunt super pedes suos, et timor magnus cecidit super eos, qui viderunt eos.',
        12: 'Et audierunt vocem magnam de caelo, dicentem eis: Ascendite huc. Et ascenderunt in caelum in nube: et viderunt illos inimici eorum.',
        13: 'Et in illa hora factus est terraemotus magnus, et decima pars civitatis cecidit: et occisa sunt in terraemotu nomina hominum septem millia: et reliqui in timorem sunt missi, et dederunt gloriam Deo caeli.',
        14: 'Vae secundum abiit: et ecce vae tertium veniet cito.',
        15: 'Et septimus angelus tuba cecinit: et factae sunt voces magnae in caelo dicentes: Factum est regnum huius mundi, Domini nostri et Christi eius, et regnabit in saecula saeculorum: Amen.',
        16: 'Et viginti quattuor seniores, qui in conspectu Dei sedent in sedibus suis, ceciderunt in facies suas, et adoraverunt Deum, dicentes:',
        17: 'Gratias agimus tibi Domine Deus noster omnipotens, qui es, et qui eras, et qui venturus es: quia accepisti virtutem tuam magnam, et regnasti.',
        18: 'Et iratae sunt Gentes, et advenit ira tua, et tempus mortuorum iudicari, et reddere mercedem servis tuis Prophetis, et sanctis, et timentibus nomen tuum pusillis, et magnis, et exterminandi eos, qui corruperunt terram.',
        19: 'Et apertum est templum Dei in caelo: et visa est arca testamenti eius in templo eius, et facta sunt fulgura, et voces, et tonitrua, et terraemotus, et grando magna.',
    },
    12: {
        1: 'Et signum magnum apparuit in caelo: Mulier amicta sole, et luna sub pedibus eius, et in capite eius corona stellarum duodecim:',
        2: 'et in utero habens, clamabat parturiens, et cruciabatur ut pariat.',
        3: 'Et visum est aliud signum in caelo: et ecce draco magnus rufus habens capita septem, et cornua decem: et in capitibus eius diademata septem,',
        4: 'et cauda eius trahebat tertiam partem stellarum caeli, et misit eas in terram, et draco stetit ante mulierem, quae erat paritura: ut cum peperisset, filium eius devoraret.',
        5: 'Et peperit filium masculum, qui recturus erat omnes Gentes in virga ferrea: et raptus est filius eius ad Deum, et ad thronum eius,',
        6: 'et mulier fugit in solitudinem ubi habebat locum paratum a Deo, ut ibi pascant eam diebus mille ducentis sexaginta.',
        7: 'Et factum est proelium magnum in caelo: Michael et angeli eius proeliabantur cum dracone, et draco pugnabat, et angeli eius:',
        8: 'et non valuerunt, neque locus inventus est eorum amplius in caelo.',
        9: 'Et proiectus est draco ille magnus, serpens antiquus, qui vocatur diabolus, et satanas, qui seducit universum orbem: et proiectus est in terram, et angeli eius cum illo missi sunt.',
        10: 'Et audivi vocem magnam in caelo dicentem: Nunc facta est salus, et virtus, et regnum Dei nostri, et potestas Christi eius: quia proiectus est accusator fratrum nostrorum, qui accusabat illos ante conspectum Dei nostri die ac nocte.',
        11: 'Et ipsi vicerunt eum propter sanguinem Agni, et propter verbum testimonii sui, et non dilexerunt animas suas usque ad mortem.',
        12: 'propterea laetamini caeli, et qui habitatis in eis. Vae terrae, et mari, quia descendit diabolus ad vos, habens iram magnam, sciens quod modicum tempus habet.',
        13: 'Et postquam vidit draco quod proiectus esset in terram, persecutus est mulierem, quae peperit masculum:',
        14: 'et datae sunt mulieri alae duae aquilae magnae ut volaret in desertum in locum suum, ubi alitur per tempus et tempora, et dimidium temporis a facie serpentis.',
        15: 'Et misit serpens ex ore suo post mulierem, aquam tamquam flumen, ut eam faceret trahi a flumine.',
        16: 'Et adiuvit terra mulierem, et aperuit terra os suum, et absorbuit flumen, quod misit draco de ore suo.',
        17: 'Et iratus est draco in mulierem: et abiit facere proelium cum reliquis de semine eius, qui custodiunt mandata Dei, et habent testimonium Iesu Christi.',
        18: 'Et stetit supra arenam maris.',
    },
    13: {
        1: 'Et vidi de mari bestiam ascendentem, habentem capita septem, et cornua decem, et super cornua eius decem diademata, et super capita eius nomina blasphemiae.',
        2: 'Et bestia, quam vidi, similis erat pardo, et pedes eius sicut pedes ursi, et os eius sicut os leonis. Et dedit illi draco virtutem suam, et potestatem magnam.',
        3: 'Et vidi unum de capitibus suis quasi occisum in mortem: et plaga mortis eius curata est. Et admirata est universa terra post bestiam.',
        4: 'Et adoraverunt draconem, qui dedit potestatem bestiae: et adoraverunt bestiam, dicentes: Quis similis bestiae? et quis poterit pugnare cum ea?',
        5: 'Et datum est ei os loquens magna, et blasphemias: et data est ei potestas facere menses quadraginta duos.',
        6: 'Et aperuit os suum in blasphemias ad Deum, blasphemare nomen eius, et tabernaculum eius, et eos, qui in caelo habitant.',
        7: 'Et est datum illi bellum facere cum sanctis, et vincere eos. Et data est illi potestas in omnem tribum, et populum, et linguam, et gentem,',
        8: 'et adoraverunt eam omnes, qui inhabitant terram: quorum non sunt scripta nomina in Libro vitae Agni, qui occisus est ab origine mundi.',
        9: 'Si quis habet aurem, audiat.',
        10: 'Qui in captivitatem duxerit, in captivitatem vadet: qui in gladio occiderit, oportet eum gladio occidi. Hic est patientia, et fides Sanctorum.',
        11: 'Et vidi aliam bestiam ascendentem de terra, et habebat cornua duo similia Agni, et loquebatur sicut draco.',
        12: 'Et potestatem prioris bestiae omnem faciebat in conspectu eius: et fecit terram, et habitantes in ea, adorare bestiam primam, cuius curata est plaga mortis.',
        13: 'Et fecit signa magna, ut etiam ignem faceret de caelo descendere in terram in conspectu hominum.',
        14: 'Et seduxit habitantes in terra propter signa, quae data sunt illi facere in conspectu bestiae, dicens habitantibus in terra, ut faciant imaginem bestiae, quae habet plagam gladii, et vixit.',
        15: 'Et datum est illi ut daret spiritum imagini bestiae, et ut loquatur imago bestiae: et faciat ut quicumque non adoraverint imaginem bestiae, occidantur.',
        16: 'Et faciet omnes pusillos, et magnos, et divites, et pauperes, et liberos, et servos habere characterem in dextera manu sua, aut in frontibus suis.',
        17: 'et nequis possit emere, aut vendere, nisi qui habet characterem, aut nomen bestiae, aut numerum nominis eius.',
        18: 'Hic sapientia est. Qui habet intellectum, computet numerum bestiae. Numerus enim hominis est: et numerus eius sexcenti sexaginta sex.',
    },
    14: {
        1: 'Et vidi: et ecce Agnus stabat supra montem Sion, et cum eo centum quadraginta quattuor millia habentes nomen eius, et nomen Patris eius scriptum in frontibus suis.',
        2: 'Et audivi vocem de caelo, tamquam vocem aquarum multarum, et tamquam vocem tonitrui magni: et vocem, quam audivi, sicut citharoedorum citharizantium in citharis suis.',
        3: 'Et cantabant quasi canticum novum ante sedem, et ante quattuor animalia, et seniores: et nemo poterat dicere canticum, nisi illa centum quadraginta quattuor millia, qui empti sunt de terra.',
        4: 'Hi sunt, qui cum mulieribus non sunt coinquinati: Virgines enim sunt. Hi sequuntur Agnum quocumque ierit. Hi empti sunt ex hominibus primitiae Deo, et Agno,',
        5: 'et in ore eorum non est inventum mendacium: sine macula enim sunt ante thronum Dei.',
        6: 'Et vidi alterum Angelum volantem per medium caeli, habentem Evangelium aeternum, ut evangelizaret sedentibus super terram, et super omnem gentem, et tribum, et linguam, et populum:',
        7: 'dicens magna voce: Timete Dominum, et date illi honorem, quia venit hora iudicii eius: et adorate eum, qui fecit caelum, et terram, mare, et fontes aquarum.',
        8: 'Et alius Angelus secutus est dicens: Cecidit, cecidit Babylon illa magna: quae a vino irae fornicationis suae potavit omnes gentes.',
        9: 'Et tertius Angelus secutus est illos, dicens voce magna: Si quis adoraverit bestiam, et imaginem eius, et acceperit characterem in fronte sua, aut in manu sua:',
        10: 'et hic bibet de vino irae Dei, quod mistum est mero in calice irae ipsius, et cruciabitur igne, et sulphure in conspectu Angelorum sanctorum, et ante conspectum Agni:',
        11: 'et fumus tormentorum eorum ascendet in saecula saeculorum: nec habent requiem die ac nocte, qui adoraverunt bestiam, et imaginem eius, et si quis acceperit characterem nominis eius.',
        12: 'Hic patientia Sanctorum est, qui custodiunt mandata Dei, et fidem Iesu.',
        13: 'Et audivi vocem de caelo, dicentem mihi: Scribe: Beati mortui, qui in Domino moriuntur. Amodo iam dicit Spiritus, ut requiescant a laboribus suis: opera enim illorum sequuntur illos.',
        14: 'Et vidi et ecce nubem candidam: et super nubem sedentem similem Filio hominis, habentem in capite suo coronam auream, et in manu sua falcem acutam.',
        15: 'Et alius Angelus exivit de templo, clamans voce magna ad sedentem super nubem: Mitte falcem tuam, et mete quia venit hora ut metatur, quoniam aruit messis terrae.',
        16: 'Et misit qui sedebat super nubem, falcem suam in terram, et demessuit eam.',
        17: 'Et alius Angelus exivit de templo, quod est in caelo, habens et ipse falcem acutam.',
        18: 'Et alius Angelus exivit de altari, qui habebat potestatem supra ignem: et clamavit voce magna ad eum, qui habebat falcem acutam, dicens: Mitte falcem tuam acutam, et vindemia botros vineae terrae: quoniam maturae sunt uvae eius.',
        19: 'Et misit Angelus falcem suam acutam in terram, et vindemiavit vineam terrae, et misit in lacum irae Dei magnum:',
        20: 'et calcatus est lacus extra civitatem, et exivit sanguis de lacu usque ad frenos equorum per stadia mille sexcenta.',
    },
    15: {
        1: 'Et vidi aliud signum in caelo magnum, et mirabile, Angelos septem, habentes plagas septem novissimas: Quoniam in illis consummata est ira Dei.',
        2: 'Et vidi tamquam mare vitreum mistum igne, et eos, qui vicerunt bestiam, et imaginem eius, et numerum nominis eius, stantes super mare vitreum, habentes citharas Dei:',
        3: 'et cantantes canticum Moysi servi Dei, et canticum Agni, dicentes: Magna, et mirabilia sunt opera tua Domine Deus omnipotens: iustae et verae sunt viae tuae, Domine Rex saeculorum.',
        4: 'Quis non timebit te Domine, et magnificabit nomen tuum? quia solus pius es: quoniam omnes gentes venient, et adorabunt in conspectu tuo, quoniam iudicia tua manifesta sunt.',
        5: 'Et post haec vidi, et ecce apertum est templum tabernaculi testimonii in caelo:',
        6: 'et exierunt septem Angeli habentes septem plagas de templo, vestiti lino mundo, et candido, et praecincti circa pectora zonis aureis.',
        7: 'Et unum de quattuor animalibus dedit septem Angelis septem phialas aureas, plenas iracundiae Dei viventis in saecula saeculorum.',
        8: 'Et impletum est templum fumo a maiestate Dei, et de virtute eius: et nemo poterat introire in templum, donec consummarentur septem plagae septem Angelorum.',
    },
    16: {
        1: 'Et audivi vocem magnam de templo, dicentem septem Angelis: Ite, et effundite septem phialas irae Dei in terram.',
        2: 'Et abiit primus Angelus, et effudit phialam suam in terram, et factum est vulnus saevum, et pessimum in homines, qui habebant characterem bestiae: et in eos, qui adoraverunt bestiam et imaginem eius.',
        3: 'Et secundus Angelus effudit phialam suam in mare, et factus est sanguis tamquam mortui: et omnis anima vivens mortua est in mari.',
        4: 'Et tertius Angelus effudit phialam suam super flumina, et super fontes aquarum, et factus est sanguis.',
        5: 'Et audivi Angelum aquarum dicentem: Iustus es Domine qui es, et qui eras sanctus, qui haec iudicasti:',
        6: 'quia sanguinem Sanctorum, et Prophetarum effuderunt, et sanguinem eis dedisti bibere: digni enim sunt.',
        7: 'Et audivi alterum dicentem: Etiam Domine Deus omnipotens vera, et iusta iudicia tua.',
        8: 'Et quartus Angelus effudit phialam suam in solem, et datum est illi aestu affligere homines, et igne:',
        9: 'et aestuaverunt homines aestu magno, et blasphemaverunt nomen Dei habentis potestatem super has plagas, neque egerunt poenitentiam ut darent illi gloriam.',
        10: 'Et quintus Angelus effudit phialam suam super sedem bestiae: et factum est regnum eius tenebrosum, et commanducaverunt linguas suas prae dolore:',
        11: 'et blasphemaverunt Deum caeli prae doloribus, et vulneribus suis, et non egerunt poenitentiam ex operibus suis.',
        12: 'Et sextus Angelus effudit phialam suam in flumen illud magnum Euphraten: et siccavit aquam eius, ut praepararetur via regibus ab ortu solis.',
        13: 'Et vidi de ore draconis, et de ore bestiae, et de ore pseudoprophetae exire spiritus tres immundos in modum ranarum.',
        14: 'Sunt enim spiritus daemoniorum facientes signa, et procedunt ad reges totius terrae congregare illos in proelium ad diem magnum omnipotentis Dei.',
        15: 'Ecce venio sicut fur. Beatus qui vigilat, et custodit vestimenta sua, ne nudus ambulet, et videant turpitudinem eius.',
        16: 'Et congregabit illos in locum, qui vocatur Hebraice Armageddon.',
        17: 'Et septimus Angelus effudit phialam suam in aerem, et exivit vox magna de templo a throno, dicens: Factum est.',
        18: 'Et facta sunt fulgura, et voces, et tonitrua, et terraemotus factus est magnus, qualis numquam fuit ex quo homines fuerunt super terram: talis terraemotus, sic magnus.',
        19: 'Et facta est civitas magna in tres partes: et civitates Gentium ceciderunt. et Babylon magna venit in memoriam ante Deum, dare illi calicem vini indignationis irae eius.',
        20: 'Et omnis insula fugit, et montes non sunt inventi.',
        21: 'Et grando magna sicut talentum descendit de caelo in homines: et blasphemaverunt Deum homines propter plagam grandinis: quoniam magna facta est vehementer.',
    },
    17: {
        1: 'Et venit unus de septem Angelis, qui habebant septem phialas, et locutus est mecum, dicens: Veni ostendam tibi damnationem meretricis magnae, quae sedet super aquas multas,',
        2: 'cum qua fornicati sunt reges terrae, et inebriati sunt qui inhabitant terram de vino prostitutionis eius.',
        3: 'Et abstulit me in spiritu in desertum. Et vidi mulierem sedentem super bestiam coccineam, plenam nominibus blasphemiae, habentem capita septem, et cornua decem.',
        4: 'Et mulier erat circumdata purpura, et coccino, et inaurata auro, et lapide pretioso, et margaritis, habens poculum aureum in manu sua, plenum abominatione, et immunditia fornicationis eius:',
        5: 'Et in fronte eius nomen scriptum: Mysterium: Babylon magna, mater fornicationum, et abominationum terrae.',
        6: 'Et vidi mulierem ebriam de sanguine sanctorum, et de sanguine martyrum Iesu. Et miratus sum cum vidissem illam admiratione magna.',
        7: 'Et dixit mihi Angelus: Quare miraris? Ego dicam tibi sacramentum mulieris, et bestiae, quae portat eam, quae habet capita septem, et cornua decem.',
        8: 'Bestia, quam vidisti, fuit, et non est, et ascensura est de abysso, et in interitum ibit: et mirabuntur inhabitantes terram (quorum non sunt scripta nomina in Libro vitae a constitutione mundi) videntes bestiam, quae erat, et non est.',
        9: 'Et hic est sensus, qui habet sapientiam. Septem capita: septem montes sunt, super quos mulier sedet, et reges septem sunt.',
        10: 'Quinque ceciderunt, unus est, et alius nondum venit: et cum venerit, oportet illum breve tempus manere.',
        11: 'Et bestia, quae erat, et non est: et ipsa octava est: et de septem est, et in interitum vadit.',
        12: 'Et decem cornua, quae vidisti, decem reges sunt: qui regnum nondum acceperunt, sed potestatem tamquam reges una hora accipient post bestiam.',
        13: 'Hi unum consilium habent, et virtutem, et potestatem suam bestiae tradent.',
        14: 'Hi cum Agno pugnabunt, et Agnus vincet illos: quoniam Dominus dominorum est, et Rex regum, et qui cum illo sunt, vocati, et electi, et fideles.',
        15: 'Et dixit mihi: Aquae, quas vidisti ubi meretrix sedet, populi sunt, et Gentes, et linguae.',
        16: 'Et decem cornua, quae vidisti in bestia: hi odient fornicariam, et desolatam facient illam, et nudam, et carnes eius manducabunt, et ipsam igne concremabunt.',
        17: 'Deus enim dedit in corda eorum ut faciant quod placitum est illi: ut dent regnum suum bestiae donec consummentur verba Dei.',
        18: 'Et mulier, quam vidisti, est civitas magna, quae habet regnum super reges terrae.',
    },
    18: {
        1: 'Et post haec vidi alium Angelum descendentem de caelo, habentem potestatem magnam: et terra illuminata est a gloria eius.',
        2: 'Et exclamavit in fortitudine, dicens: Cecidit, cecidit Babylon magna: et facta est habitatio daemoniorum, et custodia omnis spiritus immundi, et custodia omnis volucris immundae, et odibilis:',
        3: 'quia de vino irae fornicationis eius biberunt omnes gentes: et reges terrae cum illa fornicati sunt: et mercatores terrae de virtute deliciarum eius divites facti sunt.',
        4: 'Et audivi aliam vocem de caelo, dicentem: Exite de illa populus meus: ut ne participes sitis delictorum eius, et de plagis eius non accipiatis.',
        5: 'Quoniam pervenerunt peccata eius usque ad caelum, et recordatus est Dominus iniquitatum eius.',
        6: 'Reddite illi sicut et ipsa reddidit vobis: et duplicate duplicia secundum opera eius: in poculo, quo miscuit vobis, miscete illi duplum.',
        7: 'Quantum glorificavit se, et in deliciis fuit, tantum date illi tormentum et luctum: quia in corde suo dicit: Sedeo regina: et vidua non sum: et luctum non videbo.',
        8: 'Ideo in una die venient plagae eius, mors, et luctus, et fames, et igne comburetur: quia fortis est Deus, qui iudicabit illam.',
        9: 'Et flebunt, et plangent se super illam reges terrae, qui cum illa fornicati sunt, et in deliciis vixerunt, cum viderint fumum incendii eius:',
        10: 'longe stantes propter timorem tormentorum eius, dicentes: Vae, vae civitas illa magna Babylon, civitas illa fortis: quoniam una hora venit iudicium tuum.',
        11: 'Et negotiatores terrae flebunt, et lugebunt super illam: quoniam merces eorum nemo emet amplius:',
        12: 'merces auri, et argenti, et lapidis pretiosi, et margaritae, et byssi, et purpurae, et serici, et cocci, (et omne lignum thyinum, et omnia vasa eboris, et omnia vasa de lapide pretioso, et aeramento, et ferro, et marmore,',
        13: 'et cinnamomum) et amomum et odoramentorum, et unguenti, et turis, et vini, et olei, et similae, et tritici, et iumentorum, et ovium, et equorum, et rhedarum, et mancipiorum, et animarum hominum.',
        14: 'Et poma desiderii animae tuae discesserunt a te, et omnia pinguia, et praeclara perierunt a te, et amplius illa iam non invenient.',
        15: 'Mercatores horum, qui divites facti sunt, ab ea longe stabunt propter timorem tormentorum eius, flentes, ac lugentes,',
        16: 'et dicentes: Vae, vae civitas illa magna, quae amicta erat bysso, et purpura, et cocco, et deaurata erat auro, et lapide pretioso, et margaritis:',
        17: 'quoniam una hora destitutae sunt tantae divitiae, et omnis gubernator, et omnis, qui in lacum navigat, et nautae, et qui in mari operantur, longe steterunt,',
        18: 'et clamaverunt videntes locum incendii eius, dicentes: Quae similis civitati huic magnae?',
        19: 'Et miserunt pulverem super capita sua, et clamaverunt flentes, et lugentes, dicentes: Vae, vae civitas illa magna, in qua divites facti sunt omnes, qui habebant naves in mari de pretiis eius: quoniam una hora desolata est.',
        20: 'Exulta super eam caelum, et sancti Apostoli, et Prophetae: quoniam iudicavit Deus iudicium vestrum de illa.',
        21: 'Et sustulit unus Angelus fortis lapidem quasi molarem magnum, et misit in mare, dicens: Hoc impetu mittetur Babylon civitas illa magna, et ultra iam non invenietur.',
        22: 'Et vox citharoedorum, et musicorum, et tibia canentium, et tuba non audietur in te amplius: et omnis artifex omnis artis non invenietur in te amplius: et vox molae non audietur in te amplius:',
        23: 'et lux lucernae non lucebit in te amplius: et vox sponsi, et sponsae non audietur adhuc in te: quia mercatores tui erant principes terrae, quia in veneficiis tuis erraverunt omnes gentes.',
        24: 'Et in ea sanguis prophetarum et sanctorum inventus est: et omnium, qui interfecti sunt in terra.',
    },
    19: {
        1: 'Post haec audivi quasi vocem turbarum multarum in caelo dicentium: Alleluia: Laus, et gloria, et virtus Deo nostro est:',
        2: 'quia vera, et iusta iudicia sunt eius, qui iudicavit de meretrice magna, quae corrupit terram in prostitutione sua, et vindicavit sanguinem servorum suorum de manibus eius.',
        3: 'Et iterum dixerunt: Alleluia. Et fumus eius ascendit in saecula saeculorum.',
        4: 'Et ceciderunt seniores vigintiquattuor, et quattuor animalia, et adoraverunt Deum sedentem super thronum, dicentes: Amen: Alleluia.',
        5: 'Et vox de throno exivit, dicens: Laudem dicite Deo nostro omnes servi eius: et qui timetis eum pusilli, et magni.',
        6: 'Et audivi quasi vocem turbae magnae, et sicut vocem aquarum multarum, et sicut vocem tonitruorum magnorum, dicentium: Alleluia: quoniam regnavit Dominus Deus noster omnipotens.',
        7: 'Gaudeamus, et exultemus: et demus gloriam ei: quia venerunt nuptiae Agni, et uxor eius praeparavit se.',
        8: 'Et datum est illi ut cooperiat se byssino splendenti, et candido. Byssinum enim iustificationes sunt Sanctorum.',
        9: 'Et dicit mihi: Scribe: Beati, qui ad coenam nuptiarum Agni vocati sunt: et dicit mihi: Haec verba Dei vera sunt.',
        10: 'Et cecidi ante pedes eius, ut adorarem eum. Et dicit mihi: Vide ne feceris: conservus tuus sum, et fratrum tuorum habentium testimonium Iesu. Deum adora. Testimonium enim Iesu est spiritus prophetiae.',
        11: 'Et vidi caelum apertum, et ecce equus albus, et qui sedebat super eum, vocabatur Fidelis, et Verax, et cum iustitia iudicat, et pugnat.',
        12: 'Oculi autem eius sicut flamma ignis, et in capite eius diademata multa, habens nomen scriptum, quod nemo novit nisi ipse.',
        13: 'Et vestitus erat veste aspersa sanguine: et vocabatur nomen eius, Verbum Dei.',
        14: 'Et exercitus qui sunt in caelo, sequebantur eum in equis albis, vestiti byssino albo, et mundo.',
        15: 'Et de ore eius procedit gladius ex utraque parte acutus: ut in ipso percutiat Gentes. Et ipse reget eas in virga ferrea: et ipse calcat torcular vini furoris irae Dei omnipotentis.',
        16: 'Et habet in vestimento, et in foemore suo scriptum: Rex regum, et Dominus dominantium.',
        17: 'Et vidi unum Angelum stantem in sole, et clamavit voce magna, dicens omnibus avibus, quae volabant per medium caeli: Venite, et congregamini ad coenam magnam Dei:',
        18: 'ut manducetis carnes regum, et carnes tribunorum, et carnes fortium, et carnes equorum, et sedentium in ipsis, et carnes omnium liberorum, et servorum, et pusillorum, et magnorum.',
        19: 'Et vidi bestiam, et reges terrae, et exercitus eorum congregatos ad faciendum praelium cum illo, qui sedebat in equo, et cum exercitu eius.',
        20: 'Et apprehensa est bestia, et cum ea pseudopropheta: qui fecit signa coram ipso, quibus seduxit eos, qui acceperunt characterem bestiae, et qui adoraverunt imaginem eius. Vivi missi sunt hi duo in stagnum ignis ardentis sulphure:',
        21: 'Et ceteri occisi sunt in gladio sedentis super equum, qui procedit de ore ipsius: et omnes aves saturatae sunt carnibus eorum.',
    },
    20: {
        1: 'Et vidi Angelum descendentem de caelo, habentem clavem abyssi, et catenam magnam in manu sua.',
        2: 'Et apprehendit draconem, serpentem antiquum, qui est diabolus, et satanas, et ligavit eum per annos mille:',
        3: 'et misit eum in abyssum, et clausit, et signavit super illum ut non seducat amplius gentes, donec consummentur mille anni: et post haec oportet illum solvi modico tempore.',
        4: 'Et vidi sedes, et sederunt super eas, et iudicium datum est illis: et animas decollatorum propter testimonium Iesu, et propter verbum Dei, et qui non adoraverunt bestiam, neque imaginem eius, nec acceperunt characterem eius in frontibus, aut in manibus suis, et vixerunt, et regnaverunt cum Christo mille annis.',
        5: 'Ceteri mortuorum non vixerunt, donec consummentur mille anni: Haec est resurrectio prima.',
        6: 'Beatus, et sanctus, qui habet partem in resurrectione prima: in his secunda mors non habet potestatem: sed erunt sacerdotes Dei et Christi, et regnabunt cum illo mille annis.',
        7: 'Et cum consummati fuerint mille anni, solvetur satanas de carcere suo, et exibit, et seducet Gentes, quae sunt super quattuor angulos terrae, Gog, et Magog, et congregabit eos in proelium, quorum numerus est sicut arena maris.',
        8: 'Et ascenderunt super latitudinem terrae, et circuierunt castra sanctorum, et civitatem dilectam.',
        9: 'Et descendit ignis a Deo de caelo, et devoravit eos: et Diabolus, qui seducebat eos, missus est in stagnum ignis, et sulphuris, ubi et bestia,',
        10: 'et pseudopropheta cruciabuntur die ac nocte in saecula saeculorum.',
        11: 'Et vidi thronum magnum candidum, et sedentem super eum, a cuius conspectu fugit terra, et caelum, et locus non est inventus eis.',
        12: 'Et vidi mortuos magnos, et pusillos stantes in conspectu throni, et libri aperti sunt: et alius Liber apertus est qui est vitae: et iudicati sunt mortui ex his, quae scripta erant in libris secundum opera ipsorum.',
        13: 'et dedit mare mortuos, qui in eo erant: et mors, et infernus dederunt mortuos suos, qui in ipsis erant: et iudicatum est de singulis secundum opera ipsorum.',
        14: 'Et infernus et mors missi sunt in stagnum ignis. Haec est mors secunda.',
        15: 'Et qui non inventus est in Libro vitae scriptus, missus est in stagnum ignis.',
    },
    21: {
        1: 'Et vidi caelum novum, et terram novam. Primum enim caelum, et prima terra abiit, et mare iam non est.',
        2: 'Et ego Ioannes vidi sanctam civitatem Ierusalem novam descendentem de caelo, a Deo paratam, sicut sponsam ornatam viro suo.',
        3: 'Et audivi vocem magnam de throno dicentem: Ecce tabernaculum Dei cum hominibus, et habitabit cum eis. Et ipsi populus eius erunt, et ipse Deus cum eis erit eorum Deus:',
        4: 'et absterget Deus omnem lacrymam ab oculis eorum: et mors ultra non erit, neque luctus, neque clamor, neque dolor erit ultra, quia prima abierunt.',
        5: 'Et dixit qui sedebat in throno: Ecce nova facio omnia. Et dixit mihi: Scribe, quia haec verba fidelissima sunt, et vera.',
        6: 'Et dixit mihi: Factum est. ego sum alpha, et omega: initium, et finis. Ego sitienti dabo de fonte aquae vitae, gratis.',
        7: 'Qui vicerit, possidebit haec, et ero illi Deus, et ille erit mihi filius.',
        8: 'Timidis autem, et incredulis, et execratis, et homicidis, et fornicatoribus, et veneficis, et idolatris, et omnibus mendacibus, pars illorum erit in stagno ardenti igne, et sulphure: quod est mors secunda.',
        9: 'Et venit unus de septem Angelis habentibus phialas plenas septem plagis novissimis, et locutus est mecum, dicens: Veni, et ostendam tibi sponsam, uxorem Agni.',
        10: 'Et sustulit me in spiritu in montem magnum, et altum, et ostendit mihi civitatem sanctam Ierusalem descendentem de caelo a Deo,',
        11: 'habentem claritatem Dei: et lumen eius simile lapidi pretioso tamquam lapidi iaspidis, sicut crystallum.',
        12: 'Et habebat murum magnum, et altum, habentem portas duodecim: et in portis Angelos duodecim, et nomina inscripta, quae sunt nomina duodecim tribuum filiorum Israel.',
        13: 'Ab Oriente portae tres: et ab Aquilone portae tres: et ab Austro portae tres: et ab Occasu portae tres.',
        14: 'Et murus civitatis habens fundamenta duodecim, et in ipsis duodecim nomina duodecim Apostolorum Agni.',
        15: 'Et qui loquebatur mecum, habebat mensuram arundineam auream, ut metiretur civitatem, et portas eius, et murum.',
        16: 'et civitas in quadro posita est, et longitudo eius tanta est quanta et latitudo: et mensus est civitatem de arundine aurea per stadia duodecim millia: et longitudo, et altitudo, et latitudo eius aequalia sunt.',
        17: 'Et mensus est murum eius centum quadraginta quattuor cubitorum, mensura hominis, quae est angeli.',
        18: 'Et erat structura muri eius ex lapide iaspide: ipsa vero civitas aurum mundum simile vitro mundo.',
        19: 'Et fundamenta muri civitatis omni lapide pretioso ornata. Fundamentum primum, iaspis: secundum, sapphirus: tertium, calcedonius: quartum, smaragdus:',
        20: 'quintum, sardonyx: sextum, sardius: septimum, chrysolithus: octavum, beryllus: nonum, topazius: decimum, chrysoprasus: undecimum, hyacinthus: duodecimum, amethystus.',
        21: 'Et duodecim portae, duodecim margaritae sunt, per singulas: et singulae portae erant ex singulis margaritis: et platea civitatis aurum mundum, tamquam vitrum perlucidum.',
        22: 'Et templum non vidi in ea. Dominus enim Deus omnipotens templum illius est, et Agnus.',
        23: 'Et civitas non eget sole, neque luna ut luceant in ea. nam claritas Dei illuminabit eam, et lucerna eius est Agnus.',
        24: 'Et ambulabunt gentes in lumine eius: et reges terrae afferent gloriam suam, et honorem in illam.',
        25: 'Et portae eius non claudentur per diem: nox enim non erit illic.',
        26: 'Et afferent gloriam, et honorem gentium in illam.',
        27: 'Non intrabit in eam aliquod coinquinatum, aut abominationem faciens, et mendacium, nisi qui scripti sunt in libro vitae Agni.',
    },
    22: {
        1: 'Et ostendit mihi fluvium aquae vivae, splendidum tamquam crystallum, procedentem de sede Dei et Agni.',
        2: 'In medio plateae eius, et ex utraque parte fluminis lignum vitae, afferens fructus duodecim, per menses singulos reddens fructum suum, et folia ligni ad sanitatem Gentium.',
        3: 'Et omne maledictum non erit amplius: sed sedes Dei, et Agni in illa erunt, et servi eius servient illi.',
        4: 'Et videbunt faciem eius: et nomen eius in frontibus eorum.',
        5: 'Et nox ultra non erit: et non egebunt lumine lucernae, neque lumine solis, quoniam Dominus Deus illuminabit illos, et regnabunt in saecula saeculorum.',
        6: 'Et dixit mihi: Haec verba fidelissima sunt, et vera. Et Dominus Deus spirituum prophetarum misit Angelum suum ostendere servis suis quae oportet fieri cito.',
        7: 'Et ecce venio velociter. Beatus, qui custodit verba prophetiae libri huius.',
        8: 'Et ego Ioannes, qui audivi, et vidi haec. Et postquam audissem, et vidissem, cecidi ut adorarem ante pedes angeli, qui mihi haec ostendebat:',
        9: 'et dixit mihi: Vide ne feceris: conservus enim tuus sum, et fratrum tuorum prophetarum, et eorum, qui servant verba prophetiae libri huius: Deum adora.',
        10: 'Et dicit mihi: Ne signaveris verba prophetiae libri huius: tempus enim prope est.',
        11: 'Qui nocet, noceat adhuc: et qui in sordibus est, sordescat adhuc: et qui iustus est, iustificetur adhuc: et sanctus, sanctificetur adhuc.',
        12: 'Ecce venio cito, et merces mea mecum est, reddere unicuique secundum opera sua.',
        13: 'Ego sum alpha, et omega, primus, et novissimus, principium, et finis.',
        14: 'Beati, qui lavant stolas suas in sanguine Agni: ut sit potestas eorum in ligno vitae, et per portas intrent in civitatem.',
        15: 'Foris canes, et venefici, et impudici, et homicidae, et idolis servientes, et omnis, qui amat, et facit mendacium.',
        16: 'Ego Iesus misi Angelum meum, testificari vobis haec in Ecclesiis. Ego sum radix, et genus David, stella splendida, et matutina.',
        17: 'Et spiritus, et sponsa dicunt: Veni. Et qui audit, dicat: Veni. Et qui sitit, veniat: et qui vult, accipiat aquam vitae, gratis.',
        18: 'Contestor enim omni audienti verba prophetiae libri huius: Si quis apposuerit ad haec, apponet Deus super illum plagas scriptas in libro isto.',
        19: 'Et si quis diminuerit de verbis libri prophetiae huius, auferet Deus partem eius de libro vitae, et de civitate sancta, et de his, quae scripta sunt in libro isto.',
        20: 'dicit qui testimonium perhibet istorum. Etiam venio cito: Amen. Veni Domine Iesu.',
        21: 'Gratia Domini nostri Iesu Christi cum omnibus vobis. Amen.',
    },
}
